from .at_ue import AtUe
from .data_transfer.iperf.at_iperf_ue_data_transfer import AtIperfUeDataTransfer
from .data_transfer.iperf.at_iperf_ue_pc_data_transfer import AtIperfUePcDataTransfer
from .exceptions import UeAlreadyReserved


class SmawaveUE(AtUe):
    """At Ue Common"""

    data_transfer_types = {
        # tool   implementing class
        'iperf': AtIperfUeDataTransfer,
        'iperf_uepc': AtIperfUePcDataTransfer
    }

    # pylint: disable=too-many-instance-attributes, broad-except, unnecessary-pass
    def __init__(self, name, ue_pc, ue_config, prefix="sma"):
        """
        :param name: UE name from config.yml
        :param ue_pc: taf.ue.rpc.jsonrpc.Rpc object
        :param ue_config: UE configuration from config.yml, everything under CONSTRUCTOR_PARAMETERS key
        :param prefix: communication prefix
        """

        super().__init__(name, ue_pc, ue_config, prefix)

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        self._validate_ue_config()
        reserved_ues = self.ue_pc.get_reserved_ues().get("ue_ids", [])
        self.logger.debug(f"list of already reserved UEs on taf.ue.proxy: {reserved_ues}")
        if self.ue_com_port in reserved_ues:
            raise UeAlreadyReserved(
                f"UE with serial number \"{self.ue_com_port}\" cannot be reserved, because is already reserved. "
                "The reservation could be made manually or by previous Robot TC.\n"
                "Before re-execution:\n"
                "1) make sure that UE PC isn't used by other tester or Robot TC AND\n"
                "2) repair the environment:\n"
                "  a) restart taf.ue.proxy service OR\n"
                f"  b) release UE manually: open \"{self.ue_pc.remote_url}/docs\" -> open \"release_ue\" endpoint "
                f"-> button \"Try it out\" -> provide ue_id \"{self.ue_com_port}\" in request body -> button \"Execute\"")
        self.logger.debug("prepare_ue before calling reserve_ue on taf.ue.proxy")

        self.prepared = self.ue_pc.reserve_ue(ue_id=self.ue_com_port, ue_config={
            'serial_number': self.ue_config_full.get("serial_number", None),
            'ue_address': self.configuration.get("ue_address", None),
            'ue_login': self.configuration.get("ue_login", None),
            'ue_password': self.configuration.get("ue_password", None),
        })
        self._sub_access = self.prepared if self.prepared != "At" else None

        sub_access_postfix = f' sub-access: {self._sub_access}' \
            if self._sub_access else ""
        self.logger.debug(f"prepare_ue after calling reserve_ue on taf.ue.proxy{sub_access_postfix}")
        self._log_ue_pc_diagnostic_info()
        return self.prepared

    def _validate_ue_config(self):
        """Validate that required keys are present in ue_config_full."""
        required_keys = ['ue_address', 'ue_login', 'ue_password']
        missing_keys = [key for key in required_keys if key not in self.configuration]
        if missing_keys:
            raise KeyError(f"Missing required configuration key(s): {missing_keys}")
